import { sql } from "drizzle-orm"
import {
  bigint,
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
  type AnyPgColumn,
} from "drizzle-orm/pg-core"

/*
 * Drizzle schema — the source of truth for the database (database-schema.md).
 *
 * Conventions (database-schema.md):
 * - Text UUID PKs generated by the app (`crypto.randomUUID()`) — no DB default.
 * - Timestamps are timestamptz defaulting to now() (`.$defaultFn` mirrors it app-side).
 * - Secrets stored only as hashes/ciphertext (code_hash, key_hash, refresh_token_enc).
 * - RLS enabled on every table with no policies — see drizzle/0000_init.sql.
 */

export const users = pgTable(
  "users",
  {
    id: text("id").primaryKey(),
    // Verified `sub` claim — the real identity anchor.
    googleSub: text("google_sub").notNull().unique(),
    email: text("email").notNull().unique(),
    role: text("role").notNull().default("user"),
    status: text("status").notNull().default("active"),
    // Per-user daily API quota, counted over EVERY API and key the user owns (`api_configurations
    // .user_id`). `0` means unlimited; a `role = 'owner'` row is unlimited whatever this holds.
    apiLimitPerDay: integer("api_limit_per_day").notNull().default(500),
    // Chosen at registration, stored lowercase. NULL for accounts created before it, and the owner.
    username: text("username"),
    // Owner-granted permission to create invitation codes.
    canInvite: boolean("can_invite").notNull().default(false),
    // How they got in (owner: NULL). Lazy reference: invitations is defined below
    // (users ↔ invitations is the schema's one FK cycle).
    invitationId: text("invitation_id").references((): AnyPgColumn => invitations.id),
    lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    index("users_status_idx").on(t.status),
    // Duplicate-registration guard (database-schema.md §invitation_redemptions).
    uniqueIndex("users_username_idx").on(t.username),
    uniqueIndex("users_email_not_deleted_idx").on(t.email).where(sql`status <> 'deleted'`),
    check("users_role_check", sql`role in ('user', 'owner')`),
    check("users_status_check", sql`status in ('active', 'disabled')`),
    // Negative quotas are meaningless and `0` is the "unlimited" marker, so the floor is 0.
    check("users_api_limit_per_day_check", sql`api_limit_per_day >= 0`),
  ]
)

export const userProfiles = pgTable(
  "user_profiles",
  {
    userId: text("user_id")
      .primaryKey()
      .references(() => users.id, { onDelete: "cascade" }),
    displayName: text("display_name").notNull(),
    pictureUrl: text("picture_url"),
    timezone: text("timezone"),
    theme: text("theme").notNull().default("dark"),
    dashboardPrefs: jsonb("dashboard_prefs").notNull().default({}),
  },
  () => [check("user_profiles_theme_check", sql`theme in ('dark', 'light', 'system')`)]
)

export const invitations = pgTable(
  "invitations",
  {
    id: text("id").primaryKey(),
    // SHA-256 hex of `ZABER-XXXX-XXXX` — the plaintext code is never stored.
    codeHash: text("code_hash").notNull().unique(),
    label: text("label"),
    maxUses: integer("max_uses").notNull().default(1),
    uses: integer("uses").notNull().default(0),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    // Partial index for live-code lookups (redemption path).
    index("invitations_code_hash_active_idx").on(t.codeHash).where(sql`revoked_at is null`),
    check("invitations_max_uses_check", sql`max_uses >= 1`),
    check("invitations_uses_check", sql`uses >= 0 and uses <= max_uses`),
  ]
)

export const invitationRedemptions = pgTable(
  "invitation_redemptions",
  {
    id: text("id").primaryKey(),
    invitationId: text("invitation_id")
      .notNull()
      .references(() => invitations.id, { onDelete: "cascade" }),
    redeemedBy: text("redeemed_by")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    redeemedAt: timestamp("redeemed_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    // One account per redemption.
    unique("invitation_redemptions_invitation_user_unique").on(t.invitationId, t.redeemedBy),
  ]
)

export const googleConnections = pgTable(
  "google_connections",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    googleEmail: text("google_email").notNull(),
    // AES-256-GCM: base64(iv ‖ tag ‖ ciphertext), key = TOKEN_ENCRYPTION_KEY.
    refreshTokenEnc: text("refresh_token_enc").notNull(),
    scope: text("scope").notNull(),
    status: text("status").notNull().default("connected"),
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
    connectedAt: timestamp("connected_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    // Multiple Google accounts per user = multiple rows.
    unique("google_connections_user_email_unique").on(t.userId, t.googleEmail),
    index("google_connections_status_idx").on(t.status),
    check(
      "google_connections_status_check",
      sql`status in ('connected', 'reauth_required', 'disconnected')`
    ),
  ]
)

export const registeredSpreadsheets = pgTable(
  "registered_spreadsheets",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    connectionId: text("connection_id")
      .notNull()
      .references(() => googleConnections.id, { onDelete: "cascade" }),
    googleSheetId: text("google_sheet_id").notNull(),
    title: text("title").notNull(),
    // `[{ id, title, rows, columns }]` snapshot at registration.
    tabs: jsonb("tabs").notNull(),
    status: text("status").notNull().default("active"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    unique("registered_spreadsheets_user_sheet_unique").on(t.userId, t.googleSheetId),
    index("registered_spreadsheets_user_id_idx").on(t.userId),
    check("registered_spreadsheets_status_check", sql`status in ('active', 'inaccessible')`),
  ]
)

export const apiConfigurations = pgTable(
  "api_configurations",
  {
    // This PK is the public `{api_id}` — an unguessable uuid.
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    spreadsheetId: text("spreadsheet_id")
      .notNull()
      .references(() => registeredSpreadsheets.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    description: text("description"),
    tabTitle: text("tab_title").notNull(),
    headerRow: integer("header_row").notNull().default(1),
    // Required for PATCH/PUT/DELETE (D9); resolved at request time, never row numbers.
    primaryKeyColumn: text("primary_key_column"),
    // NULL = every column. Otherwise an allowlist of header names: a column added to the sheet later
    // stays hidden until its owner exposes it.
    exposedColumns: jsonb("exposed_columns").$type<string[] | null>(),
    permissions: text("permissions").notNull().default("read"),
    // Subset of ["GET","POST","PATCH","PUT","DELETE"].
    allowedOperations: jsonb("allowed_operations").notNull(),
    enabled: boolean("enabled").notNull().default(true),
    // NULL = platform default (1000/h, 10000/day).
    rateLimitPerHour: integer("rate_limit_per_hour"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    index("api_configurations_user_id_idx").on(t.userId),
    index("api_configurations_enabled_idx").on(t.enabled),
    check("api_configurations_header_row_check", sql`header_row >= 1`),
    check("api_configurations_permissions_check", sql`permissions in ('read', 'read_write')`),
  ]
)

export const apiKeys = pgTable(
  "api_keys",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    // SHA-256 hex of `sz_live_…` — the plaintext key is shown exactly once.
    keyHash: text("key_hash").notNull().unique(),
    // `sz_live_ab12…last4` — safe to display.
    keyPreview: text("key_preview").notNull(),
    scopes: jsonb("scopes").notNull().default(["read"]),
    // NULL = all of the user's APIs.
    allowedApiIds: jsonb("allowed_api_ids"),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    // Updated at most 1×/min (batched write to avoid a hot row).
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    index("api_keys_user_id_idx").on(t.userId),
    index("api_keys_key_hash_active_idx").on(t.keyHash).where(sql`revoked_at is null`),
  ]
)

export const apiRequestLogs = pgTable(
  "api_request_logs",
  {
    // Append-only, high volume: identity PK instead of uuid text.
    id: bigint("id", { mode: "number" }).generatedAlwaysAsIdentity().primaryKey(),
    // NULL for 404-on-unknown-api, and once the API is deleted: history outlives it (`api_name` stays).
    apiId: text("api_id").references(() => apiConfigurations.id, { onDelete: "set null" }),
    // The API's name when the request was served.
    apiName: text("api_name"),
    userId: text("user_id").references(() => users.id, { onDelete: "set null" }),
    // The owner's email when the request was served; removed with the row by the retention sweep.
    userEmail: text("user_email"),
    apiKeyId: text("api_key_id").references(() => apiKeys.id, { onDelete: "set null" }),
    method: text("method").notNull(),
    // `/api/v1/{id}/…` — never query strings containing data.
    path: text("path").notNull(),
    statusCode: integer("status_code").notNull(),
    durationMs: integer("duration_ms").notNull(),
    requestBytes: integer("request_bytes"),
    // auth | rate_limit | validation | google | not_found | internal
    errorCategory: text("error_category"),
    // Origin/Referer header host only. Never headers/bodies/keys/tokens/cells (spec §10).
    origin: text("origin"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    index("api_request_logs_api_created_idx").on(t.apiId, sql`${t.createdAt} desc`),
    index("api_request_logs_user_created_idx").on(t.userId, sql`${t.createdAt} desc`),
    index("api_request_logs_created_at_idx").on(t.createdAt),
  ]
)

export const auditLogs = pgTable(
  "audit_logs",
  {
    id: text("id").primaryKey(),
    // Never cascades — history outlives the record.
    actorId: text("actor_id").references(() => users.id, { onDelete: "set null" }),
    // user.disable | user.enable | invitation.create | invitation.revoke |
    // api_key.revoke_admin | settings.update | owner.bootstrap
    action: text("action").notNull(),
    subjectType: text("subject_type"),
    subjectId: text("subject_id"),
    detail: jsonb("detail").notNull().default({}),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow().$defaultFn(() => new Date()),
  },
  (t) => [
    index("audit_logs_actor_created_idx").on(t.actorId, sql`${t.createdAt} desc`),
    index("audit_logs_subject_idx").on(t.subjectType, t.subjectId),
  ]
)

export const rateLimitBuckets = pgTable("rate_limit_buckets", {
  // `{scope}:{id}:{window}` e.g. `key:<keyId>:h`
  bucketKey: text("bucket_key").primaryKey(),
  count: integer("count").notNull(),
  windowStart: timestamp("window_start", { withTimezone: true }).notNull(),
})
